#include <iostream>
#include <string>

class Item {
    std::string m_name;
    int m_qty;
    int m_price;
public:
    Item(std::string name, int qty, int price)
        : m_name{name}, m_qty{qty}, m_price{price} {}

    std::string name() const { return m_name; }
    int quantity() const { return m_qty; }
    int unitPrice() const { return m_price; }
    int total() const { return m_qty * m_price; }
};

int main() {
    int n;
    std::cin >> n;
    int grand = 0;
    for (int i = 0; i < n; ++i) {
        std::string name;
        int qty, price;
        std::cin >> name >> qty >> price;
        Item item{name, qty, price};
        std::cout << item.name() << ": qty=" << item.quantity()
                  << " price=" << item.unitPrice()
                  << " total=" << item.total() << "\n";
        grand += item.total();
    }
    std::cout << "grand_total=" << grand << "\n";
}

