#include <iostream>

class Fraction {
    int m_num;
    int m_den;
public:
    Fraction(int num, int den) : m_num{num}, m_den{den == 0 ? 1 : den} {}

    int numerator() const { return m_num; }
    int denominator() const { return m_den; }

    Fraction multiply(Fraction other) const {
        return Fraction{m_num * other.m_num, m_den * other.m_den};
    }
};

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        int n1, d1, n2, d2;
        std::cin >> n1 >> d1 >> n2 >> d2;
        Fraction a{n1, d1};
        Fraction b{n2, d2};
        Fraction p = a.multiply(b);
        std::cout << a.numerator() << "/" << a.denominator() << " * "
                  << b.numerator() << "/" << b.denominator() << " = "
                  << p.numerator() << "/" << p.denominator() << "\n";
    }
}
